# ----- validacion -----
TAGS=("[gold]","[/gold]","[blue]","[/blue]","[green]","[/green]","[sine]","[/sine]","[color=","[/color]")
ok=True
for fn,d in allfiles.items():
    e=loadeng(fn)
    if set(e)!=set(d):
        ok=False; print(f"[{fn}] CLAVES faltan={set(e)-set(d)} extra={set(d)-set(e)}")
    for k in e:
        if k not in d: continue
        ev,sv=e[k],d[k]
        for t in TAGS:
            if ev.count(t)!=sv.count(t): ok=False; print(f"[{fn}] {k}: tag {t} {ev.count(t)}!={sv.count(t)}")
        if ev.count("{")!=sv.count("{") or ev.count("}")!=sv.count("}"):
            ok=False; print(f"[{fn}] {k}: llaves {{{ev.count('{')}/{ev.count('}')}}} vs {{{sv.count('{')}/{sv.count('}')}}}")
        # tokens {Xxx} simples
        et=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',ev))
        st=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',sv))
        if et!=st: ok=False; print(f"[{fn}] {k}: tokens {et} != {st}")
        if ev.count("\\n")!=sv.count("\\n"): ok=False; print(f"[{fn}] {k}: \\n {ev.count(chr(92)+'n')} != {sv.count(chr(92)+'n')}")
print("VALIDACION OK" if ok else "REVISAR ^")
